def format_bytes(n):
    """Return a human-readable size string, e.g. '1.5 KB'."""
    for unit in ('B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'):
        if abs(n) < 1024.0:
            if unit == 'B':
                return f"{n:.0f} {unit}"
            return f"{n:.1f} {unit}"
        n /= 1024.0
    return f"{n:.1f} {unit}"
